"use client";

import { useState } from "react";
import { Truck, MapPin, ChevronRight, Package, Calendar } from "lucide-react";
import { orders, Order, OrderStatus } from "@/data/order";

// --- Sub-Components ---

const StatusBadge = ({ status, label }: { status: OrderStatus; label: string }) => {
  const styles = {
    shipping: "bg-brand/10 text-brand border-brand/20",
    arrived: "bg-green-500/10 text-green-500 border-green-500/20",
    canceled: "bg-destructive/10 text-destructive border-destructive/20",
  };
  return (
    <span className={`px-3 py-1 rounded-full text-[10px] font-bold border uppercase tracking-widest ${styles[status]}`}>
      {label}
    </span>
  );
};

const TabButton = ({ isActive, label, count, onClick }: any) => (
  <button
    onClick={onClick}
    className={`flex-1 min-w-fit flex items-center justify-center gap-2 px-4 sm:px-8 py-2.5 rounded-full text-sm font-bold transition-all whitespace-nowrap ${
      isActive
        ? "bg-background text-foreground shadow-sm scale-[0.98]"
        : "text-foreground-subtle hover:text-foreground"
    }`}
  >
    {label}
    {count !== undefined && (
      <span className={`w-5 h-5 flex items-center justify-center rounded-full text-[10px] ${
        isActive ? "bg-brand text-brand-foreground" : "bg-background-elevated text-foreground-subtle border border-border"
      }`}>
        {count}
      </span>
    )}
  </button>
);

const OrderCard = ({ order }: { order: Order }) => (
  <article className="bg-background-elevated rounded-4xl p-5 sm:p-7 border border-border shadow-sm">
    {/* Header */}
    <div className="flex items-start justify-between mb-6">
      <div className="space-y-1">
        <p className="text-[10px] text-foreground-subtle font-black uppercase tracking-[0.2em]">ID: {order.id}</p>
        <div className="flex items-center gap-2 text-foreground-muted">
          <Calendar size={14} />
          <span className="text-xs font-bold">{order.date}</span>
        </div>
      </div>
      <StatusBadge status={order.status} label={order.statusLabel} />
    </div>

    {/* Tracking Visualization */}
    <div className="bg-background-muted rounded-3xl p-4 mb-6 relative overflow-hidden">
      <div className="flex items-center justify-between relative z-10">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-full bg-background border border-border flex items-center justify-center">
            <Truck size={16} className="text-brand" />
          </div>
          <div className="hidden xs:block">
            <p className="text-[9px] text-foreground-subtle uppercase font-bold">Origin</p>
            <p className="text-xs font-bold truncate max-w-[80px]">{order.origin}</p>
          </div>
        </div>

        {/* The Animated-style Dashed Line */}
        <div className="flex-1 mx-4 h-px border-t-2 border-dashed border-border" />

        <div className="flex items-center gap-3 text-right">
          <div className="hidden xs:block">
            <p className="text-[9px] text-foreground-subtle uppercase font-bold">Destination</p>
            <p className="text-xs font-bold truncate max-w-[80px]">{order.destination}</p>
          </div>
          <div className="w-9 h-9 rounded-full bg-background border border-border flex items-center justify-center">
            <MapPin size={16} className="text-foreground-muted" />
          </div>
        </div>
      </div>
    </div>

    {/* Horizontal Product Showcase (Optimized) */}
    <div className="mb-6">
      <p className="text-[10px] text-foreground-subtle font-bold uppercase mb-3 ml-1">Items in this shipment</p>
      <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
        {order.items.map((item) => (
          <div key={item.id} className="flex-none w-48 bg-background-muted/50 border border-border/40 p-2 rounded-2xl flex gap-3 items-center">
            <div className="w-12 h-14 shrink-0 rounded-lg overflow-hidden bg-background">
              <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
            </div>
            <div className="min-w-0">
              <h4 className="text-[11px] font-bold truncate">{item.name}</h4>
              <p className="text-[10px] text-foreground-subtle">Size {item.size} • x{item.quantity}</p>
            </div>
          </div>
        ))}
      </div>
    </div>

    {/* Footer */}
    <div className="flex items-center justify-between pt-5 border-t border-border">
      <div>
        <p className="text-[10px] text-foreground-subtle font-bold uppercase">Total Amount</p>
        <p className="text-xl font-black">₹{order.totalPrice.toLocaleString()}</p>
      </div>
      <button className="bg-brand text-brand-foreground h-11 px-6 rounded-2xl font-bold text-sm flex items-center gap-2 hover:opacity-90 active:scale-95 transition-all shadow-lg shadow-brand/10">
        Track <ChevronRight size={16} />
      </button>
    </div>
  </article>
);

export default function OrdersPage() {
  const [activeTab, setActiveTab] = useState<OrderStatus>("shipping");
  const filteredOrders = orders.filter((o) => o.status === activeTab);

  return (
    <div className="min-h-screen bg-background text-foreground selection:bg-brand selection:text-brand-foreground">
      {/* Responsive Sticky Header */}
      <header className="sticky top-0 z-40 bg-background/80 backdrop-blur-md border-b border-border">
        <div className="max-w-5xl mx-auto px-4 pt-6 pb-4">
          <h1 className="text-xl font-black uppercase tracking-widest mb-6 text-center sm:text-left">My Orders</h1>
          
          <div className="bg-background-muted p-1.5 rounded-3xl flex items-center gap-1 overflow-x-auto no-scrollbar shadow-inner">
            {["shipping", "arrived", "canceled"].map((tab) => (
              <TabButton
                key={tab}
                isActive={activeTab === tab}
                label={tab === "shipping" ? "On Shipping" : tab.charAt(0).toUpperCase() + tab.slice(1)}
                count={tab !== "canceled" ? orders.filter(o => o.status === tab).length : undefined}
                onClick={() => setActiveTab(tab as OrderStatus)}
              />
            ))}
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 gap-6">
          {filteredOrders.length > 0 ? (
            filteredOrders.map((order) => <OrderCard key={order.id} order={order} />)
          ) : (
            <div className="text-center py-20 bg-background-elevated rounded-4xl border border-dashed border-border opacity-60">
              <p className="font-bold">No {activeTab} orders</p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}